/**
 * Shared orchestration for the repository and published dev shell launchers.
 *
 * It builds the worker and reads its manifest, creates one Vite middleware instance per
 * custom block, and owns resource cleanup. Each launcher entry point
 * supplies a small shell adapter, but otherwise delegates to this module.
 */
import { existsSync, mkdirSync, mkdtempSync, rmSync } from "node:fs";
import { basename, join, resolve } from "node:path";
import { buildBlockRegistry, } from "./build-block-registry.js";
import { readDataSources } from "./data-sources.js";
import { DevShellRun, installProcessSignalHandlers, } from "./dev-shell-run.js";
import { formatUnknownErrorWithStack } from "./errors.js";
import { materializeWorkerSchemaDataSources } from "./materialize.js";
import { DEFAULT_DEV_SHELL_PORT, parsePort } from "./ports.js";
import { resolveLaunchBindings } from "./resolve-bindings.js";
import { SharedServer } from "./shared-server.js";
import { parseBindingOverride, } from "./source-bindings.js";
import { parseCliArgs } from "./utils.js";
import { writeBlockViteConfig } from "./vite-block-server.js";
import { mountVite } from "./vite-middleware.js";
import { blockCapabilities, findWorkerDir, generateWorkerManifest, } from "./worker-manifest.js";
const dim = "\x1b[2m";
const bold = "\x1b[1m";
const cyan = "\x1b[36m";
const reset = "\x1b[0m";
const label = (name) => `${cyan}[${name}]${reset}`;
export async function prepareWorkerLaunchPlan(workerDir, options = {}) {
    const root = resolve(workerDir);
    if (!existsSync(resolve(root, "node_modules"))) {
        throw new Error(`No node_modules in ${root}. Install the worker's dependencies first ` +
            `(e.g. \`npm install\`), then rerun.`);
    }
    const { manifest, manifestPath } = await generateWorkerManifest(root, {
        build: options.build,
    });
    const capabilities = blockCapabilities(manifest);
    const registry = buildBlockRegistry(capabilities, options.shellPort ?? DEFAULT_DEV_SHELL_PORT);
    const configDir = options.configDir ?? join(root, ".dev-shell");
    const blocks = capabilities.map((capability, index) => {
        const blockDir = resolve(root, capability.config.source.path);
        const hostname = new URL(registry[index].url).hostname;
        return {
            capability,
            blockDir,
            hostname,
            configFile: writeBlockViteConfig(blockDir, capability, configDir, hostname),
        };
    });
    const dataDir = resolve(root, "data");
    materializeWorkerSchemaDataSources(manifest, dataDir);
    return {
        workerDir: root,
        configDir,
        dataDir,
        manifestPath,
        blocks,
        registry,
        dataSources: readDataSources(dataDir),
    };
}
export function parseWorkerLaunchArgs(argv) {
    const args = {
        worker: undefined,
        shellPort: DEFAULT_DEV_SHELL_PORT,
        strictPort: false,
        bindings: [],
    };
    let hasPositionalWorker = false;
    parseCliArgs({
        argv,
        handlers: {
            "--bind": value => {
                args.bindings.push(parseBindingOverride(value));
            },
            "--worker": value => {
                if (value.length === 0) {
                    throw new Error("--worker requires a path to a worker directory.");
                }
                // Reject --worker after a positional worker path.
                if (hasPositionalWorker) {
                    throw new Error("Cannot combine --worker with a positional worker path.");
                }
                args.worker = value;
            },
            "--port": value => {
                args.shellPort = parsePort("--port", value);
                args.strictPort = true;
            },
        },
        onUnknown: arg => {
            throw new Error(`Unknown dev shell option "${arg}". Supported: --worker <dir>, ` +
                `--port <port>, --bind <capabilityKey>.<dataSourceKey>=<sampleDataFileName>.`);
        },
        onPositional: arg => {
            // The published launcher passes its optional worker path positionally.
            // Reject a second positional path.
            if (hasPositionalWorker) {
                throw new Error("Only one positional worker path may be provided.");
            }
            // Reject a positional path after --worker.
            if (args.worker !== undefined) {
                throw new Error("Cannot combine --worker with a positional worker path.");
            }
            hasPositionalWorker = true;
            args.worker = arg;
        },
    });
    return args;
}
function logNamed(name, message) {
    console.log(`${label(name)} ${message}`);
}
function printSummary(args, registry) {
    console.log("");
    console.log(`${bold}Dev shell${reset}`);
    console.log(`  ${label("dev-shell")} ${dim}http://localhost:${args.shellPort}${reset}`);
    if (registry.length > 0) {
        console.log("");
        console.log(`${bold}Blocks${reset}`);
        for (const entry of registry) {
            console.log(`  ${label(entry.key)} ${dim}${entry.url}${reset}`);
        }
    }
    console.log("");
}
function resolveWorkerLaunch(options) {
    const args = parseWorkerLaunchArgs(options.argv);
    const workerDir = args.worker === undefined
        ? findWorkerDir(options.detectFromDir)
        : resolve(options.workerBaseDir, args.worker);
    if (workerDir === undefined) {
        throw new Error("No worker found: run from inside a worker directory, or pass --worker <dir>.");
    }
    if (args.worker === undefined) {
        console.log(`Detected a worker at ${workerDir}.`);
    }
    return { args, workerDir };
}
function logWorkerPlan(workerName, plan) {
    logNamed(workerName, `Wrote ${plan.manifestPath}`);
    if (plan.blocks.length === 0) {
        logNamed(workerName, "Worker declares no custom blocks.");
    }
    logNamed(workerName, plan.dataSources.length > 0
        ? `Data sources from data: ${plan.dataSources
            .map(source => source.name)
            .join(", ")}`
        : "No data sources — create data/<key>.json files " +
            "(format: node_modules/@notionhq/custom-blocks-dev-shell/docs/data-sources.md).");
}
function applyBindingsAndLog(args, plan, workerDir) {
    const { registryBindings } = resolveLaunchBindings(plan.blocks.map(block => block.capability), plan.dataSources, args.bindings);
    for (const entry of plan.registry) {
        const bindings = registryBindings.get(entry.key);
        if (bindings !== undefined) {
            entry.sampleFilesByDataSource = bindings;
        }
    }
    logWorkerPlan(basename(workerDir), plan);
}
export async function launchDevShell(options) {
    const { installSignalHandlers = true } = options;
    const shared = new SharedServer();
    const beforeCleanup = () => shared.close();
    const run = options.createRun?.(beforeCleanup) ?? new DevShellRun(beforeCleanup);
    if (installSignalHandlers) {
        installProcessSignalHandlers(run);
    }
    try {
        const { args, workerDir } = resolveWorkerLaunch(options);
        const originalCwd = process.cwd();
        // One worker owns the process for the run, including Vite config reloads
        // and plugin callbacks. Resolve CLI paths before changing directories.
        process.chdir(workerDir);
        run.addResource(() => process.chdir(originalCwd));
        args.shellPort = await shared.listen(args.shellPort, args.strictPort);
        const tempRoot = join(workerDir, ".dev-shell");
        mkdirSync(tempRoot, { recursive: true });
        const configDir = mkdtempSync(join(tempRoot, "run-"));
        run.addResource(() => rmSync(configDir, { recursive: true, force: true }));
        logNamed(basename(workerDir), "Extracting worker manifest...");
        const plan = await prepareWorkerLaunchPlan(workerDir, {
            shellPort: args.shellPort,
            configDir,
        });
        if (run.closing) {
            return;
        }
        applyBindingsAndLog(args, plan, workerDir);
        const closeShell = await options.createShellLaunch({
            plan,
            shared,
            log: logNamed,
        });
        if (closeShell) {
            run.addResource(closeShell);
        }
        for (const block of plan.blocks) {
            if (run.closing) {
                return;
            }
            const close = await mountVite({
                projectDir: workerDir,
                hostname: block.hostname,
                shared,
                config: { configFile: block.configFile, root: block.blockDir },
            });
            run.addResource(close);
        }
        if (run.closing) {
            return;
        }
        printSummary(args, plan.registry);
    }
    catch (error) {
        console.error(`Failed to start dev shell:\n${formatUnknownErrorWithStack(error)}`);
        process.exitCode = 1;
        run.shutdown("SIGTERM");
    }
}
